package br.com.tapeteskalke.repository; import br.com.tapeteskalke.entity.Cliente; import jakarta.persistence.LockModeType; import java.util.Optional; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface ClienteRepository extends JpaRepository<Cliente,String> { @Query("select c from Cliente c where c.deletedAt is null and (:search='' or lower(c.nome) like lower(concat('%',:search,'%')) or c.telefone like concat('%',:search,'%') or lower(coalesce(c.cidade,'')) like lower(concat('%',:search,'%'))) ") Page<Cliente> search(@Param("search")String search,Pageable pageable); @Query("select c from Cliente c where c.id=:id and c.deletedAt is null") Optional<Cliente> activeById(@Param("id")String id); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select c from Cliente c where c.id=:id") Optional<Cliente> lockById(@Param("id")String id); long countByDeletedAtIsNull(); }
